class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        dp = [[[math.inf]*3 for _ in range(3)] for _ in range(n)]
        dp[0] = cost[0]
        for i in range(1, n):
            for j in range(3):
                for k in range(3):
                    if j != k:
                        dp[i][j][k] = min(dp[i-1][j][l] + dp[i-1][k][m] for l in range(3) for m in range(3))
        return min(min(dp[n-1]))

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # Initialize the DP table with the first two houses' costs
        dp = [[0 for _ in range(3)] for _ in range(n)]
        dp[0][0], dp[0][1], dp[0][2] = cost[0]

        # Fill the DP table for the remaining houses
        for i in range(1, n):
            dp[i][0] = min(dp[i-1][1], dp[i-1][2]) + cost[i][0]
            dp[i][1] = min(dp[i-1][0], dp[i-1][2]) + cost[i][1]
            dp[i][2] = min(dp[i-1][0], dp[i-1][1]) + cost[i][2]

        # Return the minimum cost to paint the last house
        return min(dp[-1])

