class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        if n == 0:
            return 0

        # Initialize arrays to store the minimum cost for each position and color
        dp = [[float('inf')] * 3 for _ in range(n)]

        # Base case: the first house has no previous house to consider
        dp[0] = cost[0]

        # Fill the DP table for each house starting from the second house
        for i in range(1, n):
            for j in range(3):
                # Calculate the minimum cost for the current house
                dp[i][j] = min(dp[i - 1][(k + 1) % 3] for k in range(3) if k != j)

                # Add the cost of painting the current house
                dp[i][j] += cost[i][j]

        # The minimum cost to paint all houses will be the minimum of the last three colors
        return min(dp[n - 1])

