class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        if n % 2 == 1:
            return float('inf')

        # Initialize DP arrays for the last two rows
        dp_last_row = cost[0]
        dp_current_row = cost[1]

        # Iterate through each house starting from the third one
        for i in range(2, n):
            # Calculate the new cost for each color based on the previous row's costs
            dp_new_row = [
                min(dp_last_row[j] + cost[i][k] for k in range(3) if k != j)
                for j in range(3)
            ]

            # Update the DP arrays for the next iteration
            dp_last_row, dp_current_row = dp_current_row, dp_new_row

        # Return the minimum cost from the last row
        return min(dp_current_row)

