class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        @functools.lru_cache(None)
        def dfs(i, prev):
            if i >= n:
                return 0
            ans = float('inf')
            for c in range(3):
                if c == prev:
                    continue
                ans = min(ans, cost[i][c] + dfs(i+1, c))
            return ans

        return dfs(0, -1)

