class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        @functools.lru_cache(None)
        def dp(i, prev_color):
            if i == n - 1:
                return cost[i][prev_color]

            min_cost = float('inf')
            for color in range(3):
                if color != prev_color:
                    min_cost = min(min_cost, dp(i+1, color))
            return min_cost

        return min(dp(0, 0), dp(0, 1), dp(0, 2))

