def find_staring_bibs(N, P, Q):
    # Create a dictionary to map each person's bib number to their staring person's bib number
    staring_bibs = {}

    # Iterate through the list of bib numbers and their corresponding staring persons
    for bib, person in zip(Q, P):
        if bib in staring_bibs:
            staring_bibs[bib].append(person)
        else:
            staring_bibs[bib] = [person]

    # Print the staring bib numbers for each person
