def main():
    # Read input
    n = int(input())
    p = list(map(int, input().split()))
    q = list(map(int, input().split()))

    # Create an adjacency list representation of the graph
    graph = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        graph[p[i]].append(q[i])

    # Perform DFS to find the order of people
    visited = [False] * (n + 1)
    order = []
    def dfs(node):
        if not visited[node]:
            visited[node] = True
            for neighbor in graph[node]:
                dfs(neighbor)
            order.append(node)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    # Print the result
    print(' '.join(str(order[i]) for i in range(1, n + 1)))

