# Solution using Union-Find Data Structure
class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x == root_y:
            return
        if self.rank[root_x] > self.rank[root_y]:
            self.parent[root_y] = root_x
        elif self.rank[root_x] < self.rank[root_y]:
            self.parent[root_x] = root_y
        else:
            self.parent[root_y] = root_x
            self.rank[root_x] += 1

    def connected(self, x, y):
        return self.find(x) == self.find(y)

def find_bib_staring_at(N, P, Q):
    uf = UnionFind(N)
    for i in range(N):
        uf.union(P[i] - 1, Q[i] - 1)
    bib_staring_at = [uf.find(i) + 1 for i in range(N)]
    return ' '.join(map(str, bib_staring_at))

