class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        if len(digits) < 3:
            return 0

        # Count occurrences of each digit
        count = [digits.count(digit) for digit in set(digits)]

        # If any digit has more than two occurrences, it's impossible to form a valid number
        if max(count) > 2:
            return 0

        # Calculate the number of ways to choose 2 digits out of the remaining 8 digits
        ways_to_choose_2 = sum([math.comb(8 - i, 2) for i in range(3)])

        # If there are exactly two 0s, we need to subtract the cases where they are both used as the first digit
        if digits.count(0) == 2:
            ways_to_choose_2 -= math.comb(6, 2)

        return ways_to_choose_2

