class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        # Sort the digits to ensure we always choose the smallest possible even number first
        digits.sort()
        count = 0

        # Iterate over all possible choices for the hundreds place
        for i in range(1, len(digits)):
            if digits[i] % 2 == 0:
                # For each choice of the hundreds place, iterate over all possible choices for the tens place
                for j in range(i+1, len(digits)):
                    if digits[j] % 2 == 0:
                        # For each choice of the tens place, calculate the remaining digits
                        remaining_digits = digits[:i] + digits[i+1:j] + digits[j+1:]
                        # Calculate the number of ways to arrange the remaining digits as the units place
                        count += len(permutations(remaining_digits))

        return count

