class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        if len(digits) < 3:
            return 0

        # Count occurrences of each digit
        digit_count = {}
        for digit in digits:
            if digit in digit_count:
                digit_count[digit] += 1
            else:
                digit_count[digit] = 1

        # Initialize result counter
        result = 0

        # Iterate over possible first digits (must be even)
        for first_digit in {0, 2, 4, 6, 8}:
            # If first digit is 0, no other digits can be used
            if first_digit == 0:
                continue

            # Remaining digits after choosing the first digit
            remaining_digits = digits[:]
            remaining_digits.remove(first_digit)

            # Iterate over possible second digits (cannot be 0 or already used)
            for second_digit in range(10):
                if second_digit == first_digit or second_digit in remaining_digits:
                    continue

                # Remaining digits after choosing the second digit
                remaining_digits = list(remaining_digits)
                remaining_digits.remove(second_digit)

                # Calculate the number of permutations for the remaining two digits
                num_permutations = digit_count[first_digit] * digit_count[second_digit]

                # Add the number of permutations to the result
                result += num_permutations

        return result

