        n = len(s)
        dp = defaultdict(lambda: defaultdict(int))

        # Helper function to calculate the minimum cost of transforming a substring into a palindrome
        def min_cost(i, j, k):
            if i > j:
                return 0
            if dp[i][j][k] != -1:
                return dp[i][j][k]

            if k == 0:
                return 0 if s[i] != s[j] else 1

            if s[i] == s[j]:
                dp[i][j][k] = 1 + min_cost(i+1, j-1, k)
            else:
                dp[i][j][k] = max(min_cost(i+1, j, k-1), min_cost(i, j-1, k-1))

            return dp[i][j][k]

        # Calculate the minimum cost for the entire string
        min_cost_value = min_cost(0, n-1, k)

        # If the minimum cost is less than or equal to k, return the length of the original string minus the minimum cost
        if min_cost_value <= k:
            return n - min_cost_value

        # Otherwise, return the length of the longest palindromic subsequence
        return n - min_cost_value // 2

