class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # Count the frequency of each character
        char_freq = Counter(s)
        # Find the minimum frequency of characters
        min_freq = min(char_freq.values())

        # If the number of operations is less than the minimum frequency,
        # it's impossible to form a palindrome
        if k < min_freq:
            return min_freq

        # If the number of operations is enough to remove all characters,
        # it's possible to form a palindrome
        elif k >= n:
            return n

        # Otherwise, we need to find the longest palindromic subsequence
        # that can be formed using at most k operations
        dp = [[0 for _ in range(k + 1)] for _ in range(n)]

        # Fill the DP table
        for i in range(n):
            for j in range(min(i, k) + 1):
                if i == 0:
                    dp[i][j] = 1
                else:
                    if j > 0 and s[i - 1] == s[n - i]:
                        dp[i][j] = max(dp[i - 1][j], dp[i - 2][j - 1] + 2)
                    else:
                        dp[i][j] = max(dp[i - 1][j], dp[i - 2][j])

        # The result is the maximum value in the last row of the DP table
