    # Initialize a dictionary to store the frequency of each size
    size_count = {}

    # Count the frequency of each size
    for size in A:
        if size in size_count:
            size_count[size] += 1
        else:
            size_count[size] = 1

    # Calculate the number of kagamimochis
    num_kagamimochis = 0

    # Iterate through each size
    for size in size_count:
        # If the size is less than or equal to half of another size, it can be used to form a kagamimochi
        for other_size in size_count:
            if size <= other_size / 2:
                num_kagamimochis += size_count[size] * size_count[other_size]

    return num_kagamimochis

