    A.sort()
    counts = [0] * (max(A) + 1)

    for a in A:
        counts[a] += 1

    result = 0
    for i in range(1, len(counts)):
        for j in range(i, len(counts)):
            if counts[i] > 0 and counts[j] > 0:
                result += counts[i] * counts[j]

    return result

