class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        m, n = len(grid), len(grid[0])
        heap = []

        for i in range(m):
            cur_sum = 0
            for j in range(n):
                cur_sum += grid[i][j]

                if len(heap) < k:
                    heapq.heappush(heap, -cur_sum)
                elif cur_sum > -heap[0]:
                    heapq.heappop(heap)
                    heapq.heappush(heap, -cur_sum)

            # If there are more elements than k, remove the smallest one
            while len(heap) > k:
                heapq.heappop(heap)

        return -sum(heap)

