        mentions_set = set()

        for event_type, timestamp, user_id in events:
            if event_type == "MESSAGE":
                # Check if the user is online
                if user_id in online_users:
                    # Add mentions to the set
                    mentions_set.update(user_id.split())
                else:
                    # If offline, add all users to the mentions set
                    mentions_set.update(range(numberOfUsers))
            elif event_type == "OFFLINE":
                # Remove the user from the online users set
                online_users.remove(user_id)

            # Update the mentions list
            mentions[user_id] = len(mentions_set)

        return mentions

