        seen = set()
        max_sum = float('-inf')
        current_sum = 0

        for num in nums:
            if num not in seen:
                current_sum += num
                seen.add(num)
                max_sum = max(max_sum, current_sum)
            else:
                current_sum -= num
                seen.remove(num)

