class Solution:
    def maxSum(self, nums: List[int]) -> int:
        if not nums:
            return 0

        # Use a dictionary to keep track of the last occurrence of each number
        last_occurrence = {}
        current_sum = 0
        max_sum = float('-inf')

        for i, num in enumerate(nums):
            if num in last_occurrence:
                # If the current number has been seen before, start a new subarray from the next index after its last occurrence
                current_sum = i - last_occurrence[num] - 1

            current_sum += num
            max_sum = max(max_sum, current_sum)

            last_occurrence[num] = i

        return max_sum

